cd /app/data; python3 - <<'E'
import glob,csv,io,gzip
for f in sorted(glob.glob('east*')+glob.glob('lakeside*')+glob.glob('river*')+glob.glob('west*')+glob.glob('harbor*')):
    b=open(f,'rb').read()
    if b[:2]==b'\x1f\x8b': b=gzip.decompress(b)
    if b[:2] in(b'\xff\xfe',b'\xfe\xff'): t=b.decode('utf-16')
    else: t=b.decode('utf-8-sig','replace')
    d=';' if f.startswith('west') else '\t' if f.startswith('river') else '|' if f.startswith('harb') else ','
    n=None;seen=set()
    buf=''
    for l in t.split('\n'):
        if not buf and (l.startswith('#') or not l.strip()): continue
        buf+=l+'\n'
        if buf.count('"')%2: continue
        r=next(csv.reader([buf],delimiter=d)) if d==',' else l.rstrip('\r').split(d); buf=''
        if r[0] in('id','rec','t','type'): n=len(r);continue
        if len(r)!=n and f not in seen: seen.add(f);print(f,n,r)
E

mkdir -p /app/bin /app/out; cat > /app/bin/summarize.py <<'E'
#!/usr/bin/env python3
import sys, os, re, io, csv, gzip, json
import xml.etree.ElementTree as ET
from decimal import Decimal, ROUND_HALF_UP
from datetime import date, datetime, timedelta, timezone

FACT = {'kg': Decimal(1), 'g': Decimal('0.001'), 'lb': Decimal('0.45392'), 'oz': Decimal('0.02837')}
ORDER = ['central', 'south', 'east', 'river', 'north', 'west', 'harbor', 'lakeside']
MONTHS = {m: i + 1 for i, m in enumerate('jan feb mar apr may jun jul aug sep oct nov dec'.split())}
BASE_DATE = {'east': 'YMD', 'harbor': 'iso', 'lakeside': 'iso', 'river': 'MM/DD/YYYY', 'west': 'DD.MM.YYYY'}
BASE_UNIT = {'east': 'kg', 'harbor': 'kg', 'lakeside': 'kg', 'river': 'kg', 'west': 'kg', 'north': 'kg', 'central': 'kg'}
DELIM = {'east': ',', 'lakeside': ',', 'harbor': '|', 'river': '\t', 'west': ';'}
ROLES = {
    'id': ('id', 'ref'),
    'type': ('type', 'rec', 'kind', 't', 'typ'),
    'date': ('shipped', 'date', 'shipped_at'),
    'status': ('status', 'state'),
}
COLNAMES = {
    'east': {'id', 'type', 'shipped', 'gross', 'net', 'status', 'note'},
    'harbor': {'rec', 'ref', 'date', 'weight', 'state'},
    'lakeside': {'id', 'kind', 'booked', 'shipped', 'gross_kg', 'net_kg', 'status'},
    'river': {'t', 'ref', 'shipped', 'weight', 'status'},
    'west': {'id', 'typ', 'shipped', 'weight', 'status', 'note'},
}
CODES = {'D': 'delivered', 'L': 'delivered_late', 'C': 'cancelled', 'R': 'returned', 'H': 'held',
         'DLV': 'delivered', 'DLL': 'delivered_late', 'CAN': 'cancelled', 'RET': 'returned', 'HLD': 'held'}


def decode(b):
    if b[:2] == b'\x1f\x8b':
        b = gzip.decompress(b)
    if b[:3] == b'\xef\xbb\xbf':
        return b[3:].decode('utf-8', 'replace')
    if b[:2] == b'\xff\xfe':
        return b[2:].decode('utf-16-le', 'replace')
    if b[:2] == b'\xfe\xff':
        return b[2:].decode('utf-16-be', 'replace')
    if len(b) >= 2 and b[0] and b[1] == 0:
        return b.decode('utf-16-le', 'replace')
    if len(b) >= 2 and b[0] == 0 and b[1]:
        return b.decode('utf-16-be', 'replace')
    head = b[:2000].decode('latin-1')
    m = re.search(r'^#\s*charset\s*:\s*([^\s]+)', head, re.M | re.I)
    if m:
        try:
            return b.decode(m.group(1).strip(), 'replace')
        except LookupError:
            pass
    try:
        return b.decode('utf-8')
    except UnicodeDecodeError:
        return b.decode('cp1252', 'replace')


def norm_type(t):
    t = (t or '').strip().lower()
    if t in ('', 'n', 'new'):
        return 'new'
    if t in ('c', 'cor', 'corr', 'correction', 'amend'):
        return 'corr'
    if t in ('v', 'void'):
        return 'void'
    return 'new'


def idnum(s):
    m = re.match(r'^\s*SH\D*0*(\d+)\s*$', s or '', re.I)
    return int(m.group(1)) if m else None


def norm_status(s):
    s = (s or '').strip()
    if s.upper() in CODES and len(s) <= 3:
        return CODES[s.upper()]
    return re.sub(r'[\s\-]+', '_', s.lower())


def parse_date(v, form):
    """Return (y, m) UTC month of a ship date/time."""
    v = (v or '').strip()
    if not v:
        return None
    m = re.match(r'^(\d{4})-(\d\d)-(\d\d)[T ](\d\d):(\d\d)(?::(\d\d)(?:\.\d+)?)?\s*(Z|[+-]\d\d:?\d\d|[+-]\d\d)?$', v)
    if m:
        y, mo, d, h, mi, s, tz = m.groups()
        dt = datetime(int(y), int(mo), int(d), int(h), int(mi), int(s or 0))
        if tz and tz != 'Z':
            sign = 1 if tz[0] == '+' else -1
            digits = tz[1:].replace(':', '')
            off = timedelta(hours=int(digits[:2]), minutes=int(digits[2:4] or 0))
            dt = dt - sign * off
        return dt.year, dt.month
    m = re.match(r'^(\d{1,2})\s+([A-Za-z]{3})[A-Za-z]*\.?,?\s+(\d{4})$', v)
    if m:
        return int(m.group(3)), MONTHS[m.group(2).lower()]
    form = (form or 'iso').strip()
    if form.lower() == 'serial' or (re.fullmatch(r'\d+(\.\d+)?', v) and len(v) != 8 and len(v) != 7):
        d = date(1899, 12, 30) + timedelta(days=int(float(v)))
        return d.year, d.month
    if re.fullmatch(r'\d{8}', v):
        return int(v[:4]), int(v[4:6])
    if re.fullmatch(r'\d{7}', v):
        d = date(int(v[:4]), 1, 1) + timedelta(days=int(v[4:]) - 1)
        return d.year, d.month
    parts = re.findall(r'\d+', v)
    if len(parts) < 3:
        return None
    if len(parts[0]) == 4:
        return int(parts[0]), int(parts[1])
    fu = form.upper()
    if fu == 'ISO':
        fu = 'YMD'
    order = []
    for ch in fu:
        if ch in 'YMD' and ch not in order:
            order.append(ch)
    if len(order) != 3:
        order = ['D', 'M', 'Y']
    d = dict(zip(order, parts[:3]))
    return int(d['Y']), int(d['M'])


def parse_num(s, depot):
    s = s.strip()
    if depot == 'west':
        s = s.replace('.', '').replace(',', '.')
    else:
        s = s.replace(',', '')
    return Decimal(s)


def kg_of(text, unit, depot):
    m = re.match(r'^\s*([-\d.,]+)\s*(kg|g|lb|oz)?\s*$', text, re.I)
    if not m:
        return None
    if m.group(2):
        unit = m.group(2).lower()
    return parse_num(m.group(1), depot) * FACT[unit]


def split_rows(text, delim):
    """Yield ('comment', line) or ('row', fields)."""
    buf = ''
    for line in text.split('\n'):
        line = line.rstrip('\r') if not buf else line
        if not buf:
            if not line.strip():
                continue
            if line.startswith('#'):
                yield 'comment', line
                continue
        if delim == ',':
            buf += line + '\n'
            if buf.count('"') % 2:
                continue
