def parse_fixed(text):
    LAY = {
        'FW1': (42, [('id', 0, 9), ('type', 9, 10), ('ship', 10, 17), ('w', 17, 25), ('st', 25, 26)], 'g', 'doy'),
        'FW2': (43, [('type', 0, 1), ('id', 1, 10), ('ship', 10, 18), ('w', 18, 26), ('st', 26, 27)], 'cg', 'ymd'),
        'FW3': (41, [('id', 0, 9), ('ship', 9, 16), ('type', 16, 17), ('w', 17, 24), ('st', 24, 25)], 'dlb', 'doy'),
    }
    bylen = {v[0]: k for k, v in LAY.items()}
    cur = None
    seq = None
    recs = []
    for line in text.split('\n'):
        line = line.rstrip('\r')
        if not line.strip(' \x0c'):
            continue
        if 'SHIPMENT LISTING' in line or line.startswith('\x0c'):
            continue
        if line.startswith('#'):
            m = re.match(r'^#LAYOUT\s+(\w+)', line)
            if m:
                cur = m.group(1)
            m = re.match(r'^#SEQ\s+(\d+)', line)
            if m:
                seq = int(m.group(1))
            continue
        name = bylen.get(len(line))
        if name is None:
            if cur is None:
                continue
            name = cur
            line = line.ljust(LAY[name][0])
        L = LAY[name]
        f = {k: line[a:b] for k, a, b, *_ in [(x[0], x[1], x[2]) for x in L[1]]}
        num = idnum(f['id'].strip())
        if num is None:
            continue
        t = norm_type(f['type'])
        rec = {'num': num, 'type': t}
        if t != 'void':
            w = Decimal(int(f['w']))
            if L[2] == 'g':
                kg = w * FACT['g']
            elif L[2] == 'cg':
                kg = w / 100
            else:
                kg = w / 10 * FACT['lb']
            s = f['ship'].strip()
            if L[3] == 'doy':
                d = date(int(s[:4]), 1, 1) + timedelta(days=int(s[4:]) - 1)
                rec['ym'] = (d.year, d.month)
            else:
                rec['ym'] = (int(s[:4]), int(s[4:6]))
            rec['kg'] = kg
            rec['status'] = norm_status(f['st'].strip())
        recs.append(rec)
    return seq, recs


